async run() {
    const connection = this.options.database.connection(this.options.connection);
    const seeds = await loadSeeds(this.options);
    const seedConnection = createSeedContext(connection, this.options.config, this.options.container).connection;
    return withSeedLock(seedConnection, {
        tableName: this.options.lockTableName ?? DEFAULT_SEED_LOCK_TABLE,
        acquireTimeoutMs: this.options.lockAcquireTimeoutMs,
        onStaleLock: this.options.onStaleLock,
    }, async () => {
        await ensureSeedTable(seedConnection, this.options.tableName ?? DEFAULT_SEED_TABLE);
        const history = await readSeedHistory(seedConnection, this.options.tableName);
        const warnings = this.validateAppliedHistory(seeds, history);
        await upgradeTaskChecksums(seedConnection, this.options.tableName ?? DEFAULT_SEED_TABLE, seeds, history);
        const appliedNames = new Set(history.map((record) => record.name));
        const pending = seeds.filter((seed) => !appliedNames.has(seed.name));
        const skipped = seeds
            .filter((seed) => appliedNames.has(seed.name))
            .map((seed) => seed.name);
        const executed = [];
        for (const seed of pending) {
            await this.runSeed(connection, seed);
            executed.push(seed.name);
        }
        return { executed, skipped, warnings };
    });
}

async upsertOne(options) {
    const policyInput = options.writePolicy === undefined ? true : options.writePolicy;
    assertWriteEnabled(policyInput);
    const writePolicy = policyInput === true ? true : buildUpsertWritePolicy(policyInput);
    const collection = await this.collection();
    assertWritableCollection(collection);
    if (writePolicy !== true) {
        await validateWritePolicyMetadata(this.options.collections, collection, writePolicy.create, ['writePolicy', 'create']);
        await validateWritePolicyMetadata(this.options.collections, collection, writePolicy.update, ['writePolicy', 'update']);
    }
    // The Policy scope is deliberately kept out of this filter. An upsert
    // locates its target by a unique key, and a scope merged in would leave a
    // filter that is no longer one key, breaking the uniqueness judgement
    // outright. Whether the caller may touch the target is asked separately,
    // of the record that is actually there: see `updateScopeCheck`.
    const filter = await this.normalizeFilterWithoutPolicy(collection, options.filter, options.context);
    if (!filter || filter.root.items.length === 0) {
        invalid('INVALID_FILTER', 'Single mutations require a non-empty filter.', {
            collection: collection.name,
            path: ['filter'],
        });
    }
    const by = uniqueSelectorFromFilter(collection, filter, ['filter']);
    // A Policy that forbids the operation outright still refuses here.
    resolveWriteShapeNode(this.options.policy, 'update', collection);
    const createValues = applyCreateDefaults(this.options.policy, evaluateValues(options.create));
    const [createMutation, updateMutation] = await Promise.all([
        normalizeModelMutation(this.options.collections, collection, createValues.values, 'createOne', 1, { nodes: 0, clientKeys: new Set(), context: options.context }, ['create']),
        normalizeModelMutation(this.options.collections, collection, evaluateValues(options.update), 'updateOne', 1, { nodes: 0, clientKeys: new Set(), context: options.context }, ['update']),
    ]);
    assertMutationWritePolicy(createMutation, writePolicy === true ? true : writePolicy.create, ['create'], [], 'create', collection.name);
    this.assertPolicyMutationFields(collection, createMutation, 'create', ['create'], createValues.protectedFields);
    this.assertPolicyMutationFields(collection, updateMutation, 'update', [
        'update',
    ]);
    assertMutationWritePolicy(updateMutation, writePolicy === true ? true : writePolicy.update, ['update']);
    if (by.fields.some((field) => !Object.hasOwn(createMutation.values, field) ||
        createMutation.values[field] !== by.values[field])) {
        invalid('INVALID_MUTATION', 'Upsert create values must contain the same unique selector values as filter.', { collection: collection.name, path: ['create'] });

function uniqueSelectorFromFilter(collection, filter, path) {
    const nodes = filter.root.items.map((node) => {
        if (node.kind === 'condition' &&
            node.path.length === 1 &&
            collection.fields?.some((field) => field.name === node.path[0] && field.type === 'boolean') &&
            (node.operator === '$isTruly' || node.operator === '$isFalsy'))
            return {
                ...node,
                operator: '$eq',
                value: node.operator === '$isTruly',
            };
        return node;
    });
    if (filter.root.logic !== 'and' ||
        nodes.length === 0 ||
        nodes.some((node) => node.kind !== 'condition' ||
            node.path.length !== 1 ||
            node.operator !== '$eq' ||
            node.value === undefined ||
            node.value === null ||
            Array.isArray(node.value) ||
            isPlainRecord(node.value))) {
        invalid('INVALID_UNIQUE_SELECTOR', 'Upsert filter must equal one primary or unique Field set.', { collection: collection.name, path });
    }
    const conditions = nodes;
    return validateUnique(collection, {
        kind: 'unique',
        fields: conditions.map((node) => node.path[0]),
        values: Object.fromEntries(conditions.map((node) => [node.path[0], node.value])),
    }, path);

